  static const int disabled = 0;
  static const int enabled = 1;
}

/// `river_libinput_device_v1.dwtp_state`
abstract final class RiverLibinputDeviceV1DwtpState {
  static const int disabled = 0;
  static const int enabled = 1;
}

/// acceleration config
class RiverLibinputAccelConfigV1 extends Proxy {
  RiverLibinputAccelConfigV1(super.connection, super.id, super.version);

  static const WaylandInterface<RiverLibinputAccelConfigV1> interface =
      WaylandInterface('river_libinput_accel_config_v1', 1, RiverLibinputAccelConfigV1.new);

  @override
  String get interfaceName => 'river_libinput_accel_config_v1';

  /// destroy the accel object
  void destroy() {
    final WireWriter w = WireWriter(id, 0);
    send(w);
    markDestroyed();
  }

  /// define custom acceleration function
  RiverLibinputResultV1 setPoints(int type, List<int> step, List<int> points) {
    final WireWriter w = WireWriter(id, 1);
    final RiverLibinputResultV1 created = connection.createProxy(RiverLibinputResultV1.new, version);
    w.uint32(created.id);
    w.uint32(type);
    w.array(step);
    w.array(points);
    send(w);
    return created;
  }

  @override
  void dispatchEvent(int opcode, WireReader r) {
  }
}

/// `river_libinput_accel_config_v1.error`
abstract final class RiverLibinputAccelConfigV1Error {
  /// invalid enum value or similar
  static const int invalidArg = 0;
}

/// `river_libinput_accel_config_v1.accel_type`
abstract final class RiverLibinputAccelConfigV1AccelType {
  static const int fallback = 0;
  static const int motion = 1;
  static const int scroll = 2;
}

/// config application result
class RiverLibinputResultV1 extends Proxy {
  RiverLibinputResultV1(super.connection, super.id, super.version);

  static const WaylandInterface<RiverLibinputResultV1> interface =
      WaylandInterface('river_libinput_result_v1', 1, RiverLibinputResultV1.new);

  @override
  String get interfaceName => 'river_libinput_result_v1';

  /// config success
  void Function()? onSuccess;

  /// config unsupported
  void Function()? onUnsupported;

  /// config invalid
  void Function()? onInvalid;

  @override
  void dispatchEvent(int opcode, WireReader r) {
    switch (opcode) {
      case 0:
        if (destroyed) return;
        onSuccess?.call();
        markDestroyed();
      case 1:
        if (destroyed) return;
        onUnsupported?.call();
        markDestroyed();
      case 2:
        if (destroyed) return;
        onInvalid?.call();
        markDestroyed();
    }
  }
}

